package com.sarc.backend.service;
import com.sarc.backend.model.*; import com.sarc.backend.dto.*; import com.sarc.backend.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*;
@Service public class ParteService { private final ParteRepository partes; private final CitaService citas; private final UsuarioService usuarios; public ParteService(ParteRepository p,CitaService c,UsuarioService u){partes=p;citas=c;usuarios=u;}
 @Transactional public ParteMedico guardar(Long citaId,ParteRequest x){Cita c=citas.get(citaId);if(c.getFecha().atTime(c.getHora()).isAfter(LocalDateTime.now()))throw new BusinessException("La cita aún no ha sido atendida");if(x.medicoId()!=null&& !c.getMedico().getId().equals(x.medicoId()))throw new BusinessException("El médico no coincide con la cita"); ParteMedico p=partes.findByCitaId(citaId).orElseGet(ParteMedico::new);p.setCita(c);p.setMedico(c.getMedico());p.setDiagnostico(x.diagnostico());p.setTratamiento(x.tratamiento());p.setObservaciones(x.observaciones());p.setEmitidoEn(LocalDateTime.now());c.setEstado(Enums.EstadoCita.COMPLETADA);return partes.save(p);}
}
